        Id = id;
        BoardId = boardId;
        UserId = userId;
        Role = role;
        InvitedByUserId = invitedByUserId;
        JoinedAt = joinedAt;
    }

    public void ChangeRole(BoardRole newRole) => Role = newRole;
}
